import { generationStart } from './retained.js';
// Replay/history reads are bounded to a requested day, level, or recent page.
// The player picker lists prize recipients; it never enumerates every wallet's
// losing tickets just to populate a dropdown.
import { eventFacts, eventPage, eventOrdinal, activityRange } from './facts.js';
import { previousEvents } from './event-store.js';
import { dailyJackpot, dailyBoards, jackpotWin, readJackpotRoute } from './jackpots.js';
import { registrationStart } from './positions.js';
import { compareLogs, checkAbort } from './client.js';
import { uint, playerAddress } from './state.js';

export async function rngDays(s, { before, limit=60, signal }={}) {
  checkAbort(signal);
  const current=Number(await s.field('GAME', 'dailyIdx')), last=Math.min(current,before==null?current:before-1);
  checkAbort(signal);
  if(last<2||limit<1)return {days:[],nextDay:null};
  const first=Math.max(1,last-limit+1);
  // The primary jackpot read may finish while this history request waits in
  // the shared RPC lane. Its same-snapshot sealed window is already the exact
  // RNG boundary; do not locate the same event again from the chain head.
  const completed=s.completedJackpots?.get(first);
  const completedStart=Number(completed?.summary?.blockRange?.start);
  const reusableStart=completed?.status?.startsWith('resolved')&&Number(completed?.rng?.day)===first
    &&completed?.summary?.blockRange?.end!=null&&Number.isSafeInteger(completedStart)
    &&completedStart>0&&completedStart<=s.block.number;
  const knownDraw=s.jackpotDraws?.get(first);
  const knownSeal=s.jackpotSeals?.get(first);
  // The current requested day can still be waiting for its word. The view
  // reads the tagged daily-result ring (GameFacade.latestDailyResultDay /
  // DegenerusGameStorage._latestDailyResultDay), so absence is proven with
  // one snapshot read instead of searching the deployment for a future event.
  if(first===current&&!reusableStart&&!knownDraw){
    const latest=Number(await s.call('GAME','latestDailyResultDay'));
    checkAbort(signal);
    if(latest<first)return {days:[],nextDay:first>1?first:null};
  }
  // A tagged RNG event is the exact lower bound for this page of drawings.
  // Request-boundary reconstruction is needed only when that first day has no RNG.
  // DailyRngApplied.day is NOT indexed: RPC topic filters cannot select it.
  const firstRng=reusableStart?{blockNumber:completedStart}:first>1?(await previousEvents(s.client,'GAME','DailyRngApplied',
    knownDraw??knownSeal??{blockNumber:s.block.number,transactionIndex:Number.MAX_SAFE_INTEGER,logIndex:Number.MAX_SAFE_INTEGER},
    {signal,accept:row=>Number(row.args.day)===first,acceptKey:`day:${first}`})).at(-1):null;
  checkAbort(signal);
  const range=firstRng?{fromBlock:firstRng.blockNumber}:await activityRange(s,first,signal);
  checkAbort(signal);
  const events=await eventFacts(s,['DailyRngApplied','Advance','DailyWinningTraits'],{contract:'GAME',fromBlock:range.fromBlock,signal});
  checkAbort(signal);
  const daily=events.filter(e=>e.name==='DailyRngApplied');
  if(!daily.some(e=>Number(e.args.day)>=first&&Number(e.args.day)<=last))return {days:[],nextDay:first>1?first:null};
  const transitions=events.filter(e=>e.name==='Advance'&&[7,9].includes(Number(e.args.stage)));
  const boundary={blockNumber:range.fromBlock,transactionIndex:0,logIndex:-1};
  const prior=(await previousEvents(s.client,'GAME','Advance',boundary,{signal,accept:e=>[7,9].includes(Number(e.args.stage)),acceptKey:'stage-7-9'})).at(-1);
  checkAbort(signal);
  if(prior)transitions.unshift({...prior,args:{stage:String(prior.args.stage),lvl:String(prior.args.lvl)}});
  const anchorDays=new Map();
  for(const transition of transitions){
    checkAbort(signal);
    let anchor=daily.filter(e=>compareLogs(e,transition)<0).at(-1);
    if(!anchor)anchor=(await previousEvents(s.client,'GAME','DailyRngApplied',transition,{signal})).at(-1);
    checkAbort(signal);
    anchorDays.set(transition,Number(anchor?.args.day??1)+(Number(transition.args.stage)===9?1:0));
  }
  const draws=new Map(events.filter(e=>e.name==='DailyWinningTraits').map(e=>[Number(e.args.day),e.args]));
  const days=daily.filter(e=>Number(e.args.day)>=first&&Number(e.args.day)<=last).map((row)=>{
    const next=daily.find(e=>compareLogs(e,row)>0);
    const entered=transitions.find(e=>Number(e.args.stage)===7&&compareLogs(e,row)>0&&(!next||compareLogs(e,next)<0));
    const transition=entered??transitions.filter(e=>compareLogs(e,row)<0).at(-1);
    const jackpot=transition&&Number(transition.args.stage)===7, day=Number(row.args.day),draw=draws.get(day);
    return {day,finalWord:row.args.word,level:transition?Number(transition.args.lvl)+(jackpot?0:1):1,phase:jackpot?'J':'P',
      // Run 56: bonusTargetLevel 0 = a purchase day with no bonus-trait coin draw (audit 5790a946).
      // Run 57+: one board a day, never a bonus draw (bonusTraitsPacked null). See jackpots.js dailyBoards.
      dayInPhase:Math.max(1,day-(anchorDays.get(transition)??1)+1),...dailyBoards(draw)};
  });
  return {days,nextDay:first>1?first:null};
}
export async function readReplayRoute(s,url,{signal}={}){
  const p=url.pathname.split('/').filter(Boolean),q=url.searchParams;
  if(p[0]==='replay'){
    if(p[1]==='rng')return rngDays(s,{before:q.has('beforeDay')?uint(q.get('beforeDay')):undefined,limit:uint(q.get('limit')??60,120),signal});
    if(p[1]==='day'){
      const day=uint(p[2]), data=await dailyJackpot(s,day,signal),range=await activityRange(s,day,signal);
      const applied=(await eventFacts(s,['DailyRngApplied'],{contract:'GAME',day,fromBlock:range.fromBlock,signal})).at(-1);
      return {day,rng:applied?{rawWord:applied.args.word,finalWord:applied.args.word,nudges:Number(applied.args.nudges)}:null,distributions:data.winners.flatMap(w=>w.breakdown)};
    }
    if(p[1]==='distributions')return readJackpotRoute(s,new URL(`/game/jackpot/${uint(p[2])}`,url),{signal});
    if(p[1]==='tickets'){
      const level=uint(p[2]);
      const rows=q.has('day')?(await dailyJackpot(s,uint(q.get('day')),signal)).winners.map(w=>w.address)
        :(await readJackpotRoute(s,new URL(`/game/jackpot/${level}`,url),{signal})).distributions.map(w=>w.winner);
      return {level,scope:'prize-recipients',players:[...new Set(rows)].map(address=>({address,entryCount:null,totalMintedOnLevel:null}))};
    }
  }
  if(p[0]==='history'){
    // The old Decimator caller paginated from deployment. In chain mode it
    // requests exactly its target level instead.
    if(p[1]==='levels'){
      const level=uint(q.get('level')??await s.field('GAME','level'));
      const fromBlock=await registrationStart(s,Math.max(0,level-1),signal);
      // Window stamps open at the seal of the previous purchase level (audit 26ad5863), so level+3
      // is stamped only after this level and the next have both finished.
      const end=await generationStart(s,level+3,signal);
      const rows=await eventFacts(s,['Advance'],{contract:'GAME',fromBlock,toBlock:end?Number(end):undefined,signal});
      return {items:rows.filter(e=>Number(e.args.lvl)===level&&[3,7,9].includes(Number(e.args.stage))).map(e=>({level,stage:Number(e.args.stage),phase:Number(e.args.stage)===7?'JACKPOT':'PURCHASE',blockNumber:e.blockNumber})),nextCursor:null};
    }
    if(p[1]==='jackpots'){
      const level=uint(q.get('level'));
      const data=await readJackpotRoute(s,new URL(`/game/jackpot/${level}`,url),{signal});
      const before=Number(q.get('cursor')??Number.MAX_SAFE_INTEGER),limit=uint(q.get('limit')??100,200);
      const rows=data.distributions.filter(e=>eventOrdinal(e)<before).sort((a,b)=>-compareLogs(a,b));const items=rows.slice(0,limit);
      return {items:items.map(e=>({...e,distributionType:e.awardType})),nextCursor:rows.length>limit?eventOrdinal(items.at(-1)):null};
    }
    if(p[1]==='player'){
      const page=await eventPage(s,['DegeneretteBetPlaced'],url,{contract:'GAME',player:playerAddress(p[2]),signal});
      return {items:page.rows.map(e=>({...e.args,blockNumber:e.blockNumber})),nextCursor:page.nextCursor};
    }
  }
  return undefined;
}
